/// <summary>
/// MPJ_3748 - KScerri - 10/05/2021
/// Hierarchy provider class implementing <c>WorkflowHierarchyProvider</c> uses dimension value to 
/// find cost center owner's manager.
/// </summary>
class METVendProcessInvoiceWFHierarchyProvider implements WorkflowHierarchyProvider
{
    const str Workflow_Employee = METConstants::WorkflowApprovalEmployee;

    ExpressionDataSource            dataSource;
    WorkflowHierarchyProviderHelper helper;

}

Method.Source:
/// <summary>
/// MPJ_3748 - KScerri - 10/05/2021
/// Consturctor
/// </summary>
/// <returns>new constructor</returns>
public static METVendProcessInvoiceWFHierarchyProvider construct()
{
    return new METVendProcessInvoiceWFHierarchyProvider();
}

/// <summary>
/// MPJ_3748 - KScerri - 10/05/2021
/// On loading of Workflow setup provide the employee's
/// </summary>
protected void new()
{
    helper = WorkflowHierarchyProviderHelper::construct();
    dataSource = ExpressionDataSource::newDataSourceDefinition(Workflow_Employee, "@MET:PRLWorkflowApprovalEmployee");
    helper.setupDataSource(dataSource);
}

/// <summary>
/// MPJ_3748 - KScerri - 10/05/2021
/// Converts the user id to the appropriate data type
/// </summary>
/// <param name = "_userId">UserID</param>
/// <param name = "_workflowContext">Context</param>
/// <returns>DataType</returns>
public anytype convertUserIdToNodeDataType(userId _userId, WorkflowContext _workflowContext)
{
    return helper.convertUserIdToNodeDataType(_userId, _workflowContext);
}

/// <summary>
/// MPJ_3748 - KScerri - 10/05/2021
/// returns the approriate data source
/// </summary>
/// <returns>DataSource</returns>
public ExpressionDataSource getDataSource()
{
    return dataSource;
}

    /// <summary>
    /// MPJ_3748 - KScerri - 10/05/2021
    /// Returns the manager according to the level set.
    /// </summary>
    /// <param name = "_nodeId">personnel number ID</param>
    /// <param name = "_level">level of hierarchy</param>
    /// <param name = "_workflowContext">workflow context</param>
    /// <returns>cost center manager workflow node</returns>
    public WorkflowHierarchyProviderNode getNextNode(anytype _nodeId, WorkflowHierarchyLevel _level, WorkflowContext _workflowContext)
    {
        HcmPositionHierarchyType        positionHierarchyType       = HcmPositionHierarchyType::findByName(METConstants::HcmPositionHierarchyTypeName);
        HcmPositionHierarchyTypeRecId   positionHierarchyTypeRecId  = positionHierarchyType.RecId;
        
        if (positionHierarchyTypeRecId == 0)
        {
            throw error("@MET:WorkflowHierarchyProviderErrorMsg");
        }

        return helper.getNextNode(_nodeId, _level, _workflowContext, dataSource, positionHierarchyTypeRecId);
    }

/// <summary>
/// MPJ_3748 - KScerri - 10/05/2021
/// Gets node data type
/// </summary>
/// <returns>node's data type</returns>
public extendedDataTypeName getNodeDataType()
{
    return helper.getNodeDataType();
}

    /// <summary>
    /// MPJ_3748 - KScerri - 10/05/2021
    /// Addding PR dimension EDT
    /// </summary>
    /// <returns>SupportDataType</returns>
    public Set getSupportedDataType()
    {
        Set supportedDataTypes = helper.getSupportedDataType();

        if(!supportedDataTypes)
        {
            supportedDataTypes = new Set(Types::String);
        }

        //Add the required data types
        supportedDataTypes.add(extendedTypeStr(LedgerDimensionValueSet));
        return supportedDataTypes;
    }

    /// <summary>
    /// MPJ_3748 - KScerri - 10/05/2021
    /// Fetches the worker's personnel number using the field value from the record.
    /// </summary>
    /// <param name = "_dataType">data type</param>
    /// <param name = "_value">dimension recid</param>
    /// <param name = "_workflowContext">Workflow context</param>
    /// <returns>personnelNumberId</returns>
    public anytype convertToNodeDataType(extendedDataTypeName _dataType, anytype _value, WorkflowContext _workflowContext)
    {
        DimensionAttributeValueSetItem  dimensionAttributeValueSetItem;
        DimensionAttributeValue         dimensionAttributeValue;
        DimensionAttribute              dimensionAttribute;
        HcmWorker                       hcmWorker;
        VendInvoiceInfoTable            vendInvoiceInfoTable;
        PurchTable                      purchTable;
        anytype                         DimAttValueSet;

        DimAttValueSet = _value;

        // MPJ_3748 - KScerri - 12/05/2021
        // If dimension is coming from PO then get dimension from PurchTable)
        if (DimAttValueSet == 0)
        {
            vendInvoiceInfoTable = VendInvoiceInfoTable::findRecId(_workflowContext.parmRecId());
            purchTable           = purchTable::find(vendInvoiceInfoTable.PurchId);
            DimAttValueSet       = purchTable.DefaultDimension;
        }

        select firstonly PersonnelNumber from hcmWorker
        exists join dimensionAttribute
            where dimensionAttribute.name == METConstants::costCenter
        exists join DimensionAttributeValueSetItem
            where DimensionAttributeValueSetItem.DimensionAttributeValueSet == DimAttValueSet
        exists join dimensionAttributeValue
            where dimensionAttributeValue.RecId == DimensionAttributeValueSetItem.dimensionAttributeValue
                && dimensionAttributeValue.dimensionAttribute == dimensionAttribute.Recid
                && dimensionAttributeValue.owner == hcmWorker.Recid;

        return hcmWorker.PersonnelNumber;
    }
